action.mutation:
mutation CreateWorkcenterHistory($payload: [WorkcenterHistoryCreatePayloadInput!]!) {
  mutation: createWorkcenterHistory(payload: $payload) { 
    id
    number
  }
}

mutation UpdateWorkcenterHistory($payload: [WorkcenterHistoryUpdatePayloadInput!]!) {
  mutation: updateWorkcenterHistory(payload: $payload) { 
    id
    number
  }
}

mutation DeleteWorkcenterHistory($payload: [WorkcenterHistoryDeletePayloadInput!]!) {
  mutation: deleteWorkcenterHistory(payload: $payload) { 
    id
    number
  }
}
